package com.ruoyi.majorpilot.operations;

import com.ruoyi.majorpilot.analytics.metrics.*;
import com.ruoyi.majorpilot.analytics.metrics.MetricsModels.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import static com.ruoyi.majorpilot.operations.OperationsService.*;

/** Reads one consistent fact snapshot, deliberately independent of admin pagination. */
@Service @Profile("local")
public class OperationsMetrics {
    private final OperationsService ops;private final TransactionTemplate read;
    public OperationsMetrics(OperationsService ops){this.ops=ops;read=new TransactionTemplate(ops.tx.getTransactionManager());read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
    public Overview overview(long operator,OperationsDtos.Filters f){ops.audit.operator(operator,false,false);return read.execute(t->compute(snapshot(f.asOf()),f));}
    public Overview compute(Snapshot snapshot,OperationsDtos.Filters f){try{return new MetricsEngine().compute(snapshot,new Query(f.asOf(),f.from(),f.to(),new Filters(f.majorCode(),f.taskVersionId(),f.questionnaireVersion(),f.recommendationRuleVersion())));}catch(MetricsQualityException invalid){throw new com.ruoyi.majorpilot.shared.ApiException(503,"METRICS_SOURCE_INVALID");}}
    public Snapshot snapshot(Instant asOf){
        var db=ops.db;var cutoff=Timestamp.from(asOf);List<Instant> updated=new ArrayList<>();
        var students=db.queryForList("SELECT id,status,analytics_exclusion_code,created_at,email_verified_at,updated_at FROM mp_student_account WHERE created_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"updated_at"),asOf);mark(updated,time(r,"created_at"),asOf);mark(updated,time(r,"email_verified_at"),asOf);return new Student(n(r,"id"),s(r,"status"),s(r,"analytics_exclusion_code"),time(r,"created_at"),time(r,"email_verified_at"));}).toList();
        var runs=db.queryForList("SELECT r.*,m.code AS major_code,t.public_id AS task_public_id,p.questionnaire_version,rec.rule_version FROM mp_experience_run r LEFT JOIN mp_major m ON m.id=r.major_id LEFT JOIN mp_task_version t ON t.id=r.task_version_id LEFT JOIN mp_decision_profile p ON p.id=r.decision_profile_id LEFT JOIN mp_recommendation rec ON rec.id=r.source_recommendation_id WHERE r.created_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"updated_at"),asOf);mark(updated,time(r,"created_at"),asOf);mark(updated,time(r,"started_at"),asOf);mark(updated,time(r,"closed_at"),asOf);return new Run(n(r,"id"),n(r,"student_id"),nullable(r,"origin_run_id"),s(r,"content_kind"),s(r,"run_mode"),s(r,"major_code"),s(r,"task_public_id"),s(r,"questionnaire_version"),s(r,"rule_version"),time(r,"created_at"),time(r,"started_at"),time(r,"closed_at"));}).toList();
        var reports=db.queryForList("SELECT * FROM mp_report WHERE first_ready_at IS NOT NULL AND first_ready_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"first_ready_at"),asOf);List<Long> sources;if("EXPERIENCE".equals(s(r,"report_type")))sources=List.of(n(r,"experience_run_id"));else sources=db.queryForList("SELECT p.experience_run_id FROM mp_comparison_source x JOIN mp_report_version v ON v.id=x.source_experience_report_version_id JOIN mp_report p ON p.id=v.report_id WHERE x.comparison_report_version_id=(SELECT id FROM mp_report_version WHERE report_id=? AND status IN ('READY','SUPERSEDED') AND completed_at<=? ORDER BY version_no LIMIT 1) ORDER BY p.major_id",Long.class,n(r,"id"),cutoff);return new Report(n(r,"id"),n(r,"student_id"),s(r,"report_type"),sources,time(r,"first_ready_at"));}).toList();
        var surveys=db.queryForList("SELECT * FROM mp_student_feedback WHERE survey_version IS NOT NULL AND report_id IS NOT NULL AND created_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"created_at"),asOf);var value=ops.json(r.get("answers_json")).path("insightResponse");return new Survey(n(r,"id"),n(r,"student_id"),n(r,"report_id"),s(r,"survey_version"),Boolean.TRUE.equals(r.get("first_valid_survey"))||r.get("first_valid_survey") instanceof Number number&&number.intValue()==1,insight(value),time(r,"created_at"));}).toList();
        var intakes=db.queryForList("SELECT i.*,(SELECT MIN(submitted_at) FROM mp_decision_profile p WHERE p.intake_session_id=i.id) AS submitted_at FROM mp_intake_session i WHERE i.created_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"updated_at"),asOf);mark(updated,time(r,"created_at"),asOf);mark(updated,time(r,"submitted_at"),asOf);mark(updated,time(r,"claimed_at"),asOf);return new Intake(n(r,"id"),nullable(r,"claimed_student_id"),s(r,"questionnaire_version"),time(r,"created_at"),time(r,"submitted_at"),time(r,"claimed_at"));}).toList();
        var observations=new ArrayList<Observation>();for(var r:db.queryForList("SELECT e.*,n.source_run_id FROM mp_product_event e LEFT JOIN mp_recommendation n ON n.id=e.recommendation_id WHERE e.received_at<=?",cutoff)){mark(updated,time(r,"received_at"),asOf);Long run=nullable(r,"experience_run_id");if(run==null&&"next_recommendation.viewed".equals(s(r,"event_name")))run=nullable(r,"source_run_id");observations.add(new Observation(s(r,"event_id"),s(r,"event_name"),nullable(r,"student_id"),nullable(r,"intake_session_id"),run,nullable(r,"report_id"),s(r,"step_key"),time(r,"received_at")));}
        for(var r:db.queryForList("SELECT e.public_id,e.experience_run_id,e.step_key,e.created_at,r.student_id FROM mp_execution_record e JOIN mp_experience_run r ON r.id=e.experience_run_id WHERE e.status IN ('FAILED','TIMED_OUT') AND e.created_at<=?",cutoff)){mark(updated,time(r,"created_at"),asOf);observations.add(new Observation("execution:"+s(r,"public_id"),"experience.execution.failed",n(r,"student_id"),null,n(r,"experience_run_id"),null,s(r,"step_key"),time(r,"created_at")));}
        var completions=db.queryForList("SELECT s.experience_run_id,s.step_key,c.completed_at FROM mp_step_completion c JOIN mp_step_state s ON s.id=c.step_state_id WHERE c.completed_at<=?",cutoff).stream().map(r->{mark(updated,time(r,"completed_at"),asOf);return new StepCompletion(n(r,"experience_run_id"),s(r,"step_key"),time(r,"completed_at"));}).toList();
        var tasks=db.queryForList("SELECT t.public_id,t.manifest_json,m.code FROM mp_task_version t JOIN mp_major m ON m.id=t.major_id WHERE t.content_kind='MAJOR' AND EXISTS(SELECT 1 FROM mp_experience_run r WHERE r.task_version_id=t.id AND r.content_kind='MAJOR' AND r.run_mode='STANDARD' AND r.started_at<=?)",cutoff).stream().map(r->{List<String> steps=new ArrayList<>();ops.json(r.get("manifest_json")).path("steps").forEach(step->steps.add(step.path("stepKey").asText()));return new TaskDefinition(s(r,"public_id"),s(r,"code"),steps);}).toList();
        return new Snapshot(updated.stream().max(Comparator.naturalOrder()).orElse(null),students,intakes,runs,reports,surveys,observations,completions,tasks);
    }
    static Integer insight(com.fasterxml.jackson.databind.JsonNode value){if(value==null||value.isMissingNode()||value.isNull())return null;if(!value.isIntegralNumber()||!value.canConvertToInt()||value.intValue()<1||value.intValue()>5)throw new com.ruoyi.majorpilot.shared.ApiException(503,"METRICS_SOURCE_INVALID");return value.intValue();}
    private static void mark(List<Instant> all,Instant value,Instant asOf){if(value!=null&&!value.isAfter(asOf))all.add(value);}
}
